package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootCurrentCardScopeTest {
 @Test public void exactlyThreeIndependentReadSlots(){assertTrue(RootCurrentCardScope.ACTIVE);assertEquals(3,RootCurrentCardScope.MAX_FRAMES);assertEquals(15,RootCurrentCardScope.SOURCE_TASK_ID);Set<String> slots=new HashSet<>();for(int i=1;i<=3;i++)assertTrue(slots.add(RootCurrentCardScope.slot(i)));assertEquals(Set.of("READ_1","READ_2","READ_3"),slots);for(int i:new int[]{-1,0,4,Integer.MAX_VALUE})assertThrows(SecurityException.class,()->RootCurrentCardScope.slot(i));}
 @Test public void original180sAdmission(){long s=RootCurrentCardScope.STARTS_UTC,e=RootCurrentCardScope.EXPIRES_UTC;assertFalse(RootCurrentCardScope.current(s-1));assertTrue(RootCurrentCardScope.current(s));assertFalse(RootCurrentCardScope.current(e));assertTrue(RootCurrentCardScope.admissionCurrent(e-180001));assertFalse(RootCurrentCardScope.admissionCurrent(e-180000));assertEquals(181000,RootCurrentCardScope.sessionDeadline(1000,s));}
 @Test public void readDeadlineCannotExtendParentOrWindow(){long u=RootCurrentCardScope.STARTS_UTC;assertEquals(91000,RootCurrentCardScope.deadline(1000,u,181000));assertEquals(1500,RootCurrentCardScope.deadline(1000,u,1500));assertEquals(1001,RootCurrentCardScope.deadline(1000,RootCurrentCardScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidTimesFailClosed(){long u=RootCurrentCardScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootCurrentCardScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootCurrentCardScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootCurrentCardScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootCurrentCardScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootCurrentCardScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void namespaceNeverReusesPriorScopes(){assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertThrows(SecurityException.class,()->RootCurrentCardScope.store(null,1));assertNotEquals(RootReturnReadScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertNotEquals(RootCurrentReadScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);}
 @Test public void invalidMetadataBeforeAnyWrite()throws Exception{var st=RootCurrentCardScope.store(Path.of("unused"),1);assertThrows(SecurityException.class,()->st.burn("invalid","safe"));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));}
 @Test public void durableReadOnlyNoReturnTapOrRecoveryPrimitive()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootCurrentCardScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootCurrentCardScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("burnReturn"));assertFalse(s.contains("\"RETURN\""));assertFalse(s.contains("burnAction"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=3 maxTap=0 maxReturn=0"));}
}
